-- =====================================================================================================
-- Reports v3 differential evidence (Batch 7, Phase E; implementation_plan.md Batch 7). Disposable synthetic
-- databases only, through scripts/run_reports_v3_differential.sh: no production project, credentials or data.
--
-- The code under test (public.get_report_*_v3, private.report_v3_*) is compared with the frozen reviewed baseline:
-- schema rtref, generated by scripts/reports_v3_reference.py from 4236b8a with only the documented reference-only
-- cast repair, every input and the output checked against supabase/tests/reference/reports_v3_reference_manifest.json.
-- Both sides run in one REPEATABLE READ snapshot with the same now(), as the same persona (JWT claims, role
-- authenticated). Payloads are compared by jsonb equality, which keeps array order.
--
-- Every reader case comes from the pinned inventory (rt.dx_expected) with its expected outcome type: an expected
-- payload must be a payload on both sides and equal; an expected refusal must be that SQLSTATE with the same message
-- on both sides. A matching error never stands in for an expected payload, and a case outside the inventory never
-- runs. The only allowed difference is an approved one listed in the manifest (approved_differences), checked key by
-- key against counts derived from the baseline's own call facts, never from the code under test.
--
-- Part 1 (above the scale marker) runs on the functional fixtures; part 2 on the 500k scale organization.
-- =====================================================================================================
-- Output paths come from the runner; without them the evidence is discarded, never written into the working tree.
\if :{?dx_cases}
\else
\set dx_cases /dev/null
\endif
\if :{?dx_summary}
\else
\set dx_summary /dev/null
\endif
SET statement_timeout = 0;
SET jit = off;
CREATE TABLE rt.dx_results (part text NOT NULL, kind text NOT NULL, label text NOT NULL, reader text, expected text,
                            cand text, ref text,
                            outcome text NOT NULL CHECK (outcome IN ('payload_equal', 'refusal_equal', 'equal', 'mismatch')),
                            cand_sha256 text, ref_sha256 text, detail text);
CREATE FUNCTION rt.dx_sha(p jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT encode(sha256(convert_to(coalesce(p::text, 'null'), 'UTF8')), 'hex') $$;
-- Deterministic synthetic ids for adversarial inputs (no random values, so every run compares the same cases).
CREATE FUNCTION rt.dx_uuid(p text) RETURNS uuid LANGUAGE sql IMMUTABLE AS $$ SELECT md5('dx:' || p)::uuid $$;

-- The nine readers of either schema, executable by authenticated only inside the comparison transaction.
CREATE FUNCTION rt.dx_grants(p_on boolean) RETURNS void LANGUAGE plpgsql AS $$
DECLARE f regprocedure;
BEGIN
  FOR f IN SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
            WHERE n.nspname IN ('public', 'rtref') AND p.proname = ANY (rt.v3_readers()) LOOP
    EXECUTE format(CASE WHEN p_on THEN 'GRANT EXECUTE ON FUNCTION %s TO authenticated'
                        ELSE 'REVOKE EXECUTE ON FUNCTION %s FROM authenticated' END, f);
  END LOOP;
END $$;

-- One reader call as the persona: {"kind":"payload","value":...} or {"kind":"refusal","sqlstate":...,"message":...}.
-- The role change lives and dies inside the subtransaction.
CREATE FUNCTION rt.dx_call(p_uid uuid, p_org uuid, p_sql text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE v jsonb;
BEGIN
  PERFORM rt.claims(p_uid, p_org);
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    EXECUTE p_sql INTO v;
    EXECUTE 'RESET ROLE';
    RETURN jsonb_build_object('kind', 'payload', 'value', v);
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('kind', 'refusal', 'sqlstate', SQLSTATE, 'message', SQLERRM);
  END;
END $$;
CREATE FUNCTION rt.dx_reader_sql(p_schema text, p_reader text, p_start date, p_end date, p_agent uuid, p_scope text)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN p_reader = 'scope' THEN format('SELECT %I.get_report_scope_v3(%L)', p_schema, p_scope)
              ELSE format('SELECT %I.get_report_%s_v3(%L::date, %L::date, %L::uuid, %L)', p_schema, p_reader, p_start, p_end,
                          p_agent, p_scope) END $$;

-- KPI 24's quality object in a summary payload (the totals envelope; by_agent envelopes carry no quality), and the
-- payload with that one object replaced.
CREATE FUNCTION rt.dx_kpi24_quality(p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
  SELECT e #> '{detail,quality}' FROM jsonb_array_elements(p -> 'metrics') e WHERE (e ->> 'id')::int = 24 $$;
CREATE FUNCTION rt.dx_with_kpi24_quality(p jsonb, q jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE WHEN q IS NULL OR p -> 'metrics' IS NULL THEN p ELSE jsonb_set(p, '{metrics}',
    (SELECT jsonb_agg(CASE WHEN (x.e ->> 'id')::int = 24 THEN jsonb_set(x.e, '{detail,quality}', q) ELSE x.e END ORDER BY x.o)
       FROM jsonb_array_elements(p -> 'metrics') WITH ORDINALITY x(e, o))) END $$;
-- The approved KPI 24 amendment ('kpi24-quality-a1', a pre-release amendment to 3.0.0): the quality object the
-- amended summary must emit, derived from the baseline's quality object and from row counts of the baseline's own
-- call facts (rtref.report_v3_call_facts) and public.calls, for the scope and window the shared v2 helpers resolve.
--   inconsistent            new: non-conflicting terminal_non_answer attempt rows with a recorded duration > 0
--   provider_confirmed      minus those rows, minus non-conflicting provider or terminal_non_answer rows with no
--                           recorded duration (a missing duration is not a recorded zero), and minus non-conflicting
--                           terminal_non_answer rows recorded below 0 (confirmed only at exactly 0; the writer refuses <0)
--   unknown                 plus non-conflicting rows with no recorded duration that were not already legacy_unknown
--   estimated, conflicting, duplicates_excluded: unchanged.
-- Without the approval the baseline object is returned unchanged, so any difference is a mismatch.
CREATE FUNCTION rt.dx_kpi24_expected(p_uid uuid, p_org uuid, p_start date, p_end date, p_agent uuid, p_scope text,
                                     p_ref jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE a record; w record; d record;
BEGIN
  IF p_ref IS NULL OR NOT (SELECT m.approved_differences ? 'kpi24-quality-a1' FROM rt.dx_manifest m) THEN
    RETURN p_ref;
  END IF;
  PERFORM rt.claims(p_uid, p_org);
  SELECT * INTO a FROM private.report_access_v2(p_scope, p_agent);
  SELECT * INTO w FROM private.report_window(a.org_id, p_start, p_end);
  SELECT count(*) FILTER (WHERE NOT f.duration_conflict AND f.duration_source = 'terminal_non_answer' AND c.duration > 0) AS inconsistent,
         count(*) FILTER (WHERE NOT f.duration_conflict AND c.duration IS NULL
                            AND f.duration_source IN ('provider', 'terminal_non_answer')) AS confirmed_without_duration,
         -- A non-answer is confirmed only at a recorded 0: a negative recorded value (the writer refuses one) is neither.
         count(*) FILTER (WHERE NOT f.duration_conflict AND f.duration_source = 'terminal_non_answer' AND c.duration < 0)
           AS negative_non_answer,
         count(*) FILTER (WHERE NOT f.duration_conflict AND c.duration IS NULL
                            AND f.duration_source IS DISTINCT FROM 'legacy_unknown') AS unknown_added
    INTO d
    FROM rtref.report_v3_call_facts(a.org_id, w.start_at, w.end_at) f
    JOIN public.calls c ON c.id = f.call_id AND c.organization_id = a.org_id
   WHERE f.is_attempt AND (a.agent_ids IS NULL OR f.placing_agent_id = ANY (a.agent_ids));
  RETURN p_ref || jsonb_build_object(
    'inconsistent', d.inconsistent,
    'provider_confirmed', (p_ref ->> 'provider_confirmed')::bigint - d.inconsistent - d.confirmed_without_duration
                          - d.negative_non_answer,
    'unknown', (p_ref ->> 'unknown')::bigint + d.unknown_added);
END $$;

-- One reader case: candidate and reference, then the pinned expectation decides.
CREATE FUNCTION rt.dx_case(p_part text, p_label text, p_uid uuid, p_org uuid, p_reader text, p_start date, p_end date,
                           p_agent uuid, p_scope text, p_expected text) RETURNS text LANGUAGE plpgsql AS $$
DECLARE n jsonb; o jsonb; outcome text; detail text; q_ref jsonb; q_want jsonb;
BEGIN
  n := rt.dx_call(p_uid, p_org, rt.dx_reader_sql('public', p_reader, p_start, p_end, p_agent, p_scope));
  o := rt.dx_call(p_uid, p_org, rt.dx_reader_sql('rtref', p_reader, p_start, p_end, p_agent, p_scope));
  IF p_expected = 'payload' AND n ->> 'kind' = 'payload' AND o ->> 'kind' = 'payload' THEN
    IF p_reader = 'summary' THEN
      q_ref := rt.dx_kpi24_quality(o -> 'value');
      q_want := rt.dx_kpi24_expected(p_uid, p_org, p_start, p_end, p_agent, p_scope, q_ref);
      IF rt.dx_kpi24_quality(n -> 'value') IS NOT DISTINCT FROM q_want
         AND rt.dx_with_kpi24_quality(n -> 'value', q_ref) = o -> 'value' THEN
        outcome := 'payload_equal';
      ELSE
        detail := 'kpi24 got ' || coalesce(rt.dx_kpi24_quality(n -> 'value')::text, 'null') || ' want '
                  || coalesce(q_want::text, 'null');
      END IF;
    ELSIF n -> 'value' = o -> 'value' THEN
      outcome := 'payload_equal';
    END IF;
  ELSIF p_expected LIKE 'refusal:%' AND n ->> 'kind' = 'refusal' AND n = o
        AND 'refusal:' || (n ->> 'sqlstate') = p_expected THEN
    outcome := 'refusal_equal';
  END IF;
  IF outcome IS NULL THEN
    outcome := 'mismatch';
    detail := coalesce(detail || '; ', '') || 'expected ' || p_expected || ', candidate ' || (n ->> 'kind')
              || coalesce(' ' || (n ->> 'sqlstate'), '') || ', reference ' || (o ->> 'kind') || coalesce(' ' || (o ->> 'sqlstate'), '')
              || ': ' || left(coalesce(n ->> 'message', n ->> 'value', ''), 160) || ' <> ' || left(coalesce(o ->> 'message', o ->> 'value', ''), 160);
  END IF;
  INSERT INTO rt.dx_results VALUES (p_part, 'reader', p_label, p_reader, p_expected,
    coalesce(n ->> 'kind', '') || coalesce(':' || (n ->> 'sqlstate'), ''), coalesce(o ->> 'kind', '') || coalesce(':' || (o ->> 'sqlstate'), ''),
    outcome, rt.dx_sha(n), rt.dx_sha(o), detail);
  RETURN outcome;
END $$;
-- The same case as a probe that must not mismatch (the self-controls below require it to fail when planted).
CREATE FUNCTION rt.dx_must_match(p_label text, p_uid uuid, p_org uuid, p_reader text, p_start date, p_end date,
                                 p_agent uuid, p_scope text, p_expected text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF rt.dx_case('control', p_label, p_uid, p_org, p_reader, p_start, p_end, p_agent, p_scope, p_expected) = 'mismatch' THEN
    RAISE EXCEPTION 'differential mismatch: %', p_label;
  END IF;
END $$;

-- Every case of the pinned inventory, and only those.
CREATE FUNCTION rt.dx_reader_matrix() RETURNS void LANGUAGE plpgsql AS $$
DECLARE c record;
BEGIN
  FOR c IN SELECT * FROM rt.dx_expected ORDER BY who, org, scope NULLS FIRST, agent NULLS FIRST, reader, start_date, end_date LOOP
    IF rt.v3(c.who) IS NULL OR rt.v3(c.org) IS NULL OR (c.agent IS NOT NULL AND rt.v3(c.agent) IS NULL) THEN
      RAISE EXCEPTION 'differential inventory: % in % (agent %) is not in the fixtures', c.who, c.org, c.agent;
    END IF;
    PERFORM rt.dx_case('fixtures', concat_ws(':', c.who, coalesce(c.scope, '-'), coalesce(c.agent, '-'), c.reader,
                                             coalesce(c.start_date || '..' || c.end_date, '-')),
                       rt.v3(c.who), rt.v3(c.org), c.reader, c.start_date, c.end_date, rt.v3(c.agent), c.scope, c.expected);
  END LOOP;
END $$;

-- Identity-state resolver: the code under test against the baseline body on adversarial key arrays, per
-- organization (deterministic inputs).
CREATE TABLE rt.dx_ist_cases AS
WITH org AS (SELECT DISTINCT organization_id AS id FROM public.leads),
     base AS (
       SELECT o.id AS org,
              ARRAY(SELECT 'lead:' || l.id FROM public.leads l WHERE l.organization_id = o.id ORDER BY l.id)
              || ARRAY(SELECT 'client:' || c.id FROM public.clients c WHERE c.organization_id = o.id ORDER BY c.id) AS own,
              ARRAY(SELECT 'lead:' || l.id FROM public.leads l WHERE l.organization_id <> o.id ORDER BY l.id LIMIT 20)
              || ARRAY(SELECT 'client:' || c.id FROM public.clients c WHERE c.organization_id <> o.id ORDER BY c.id LIMIT 20) AS foreign_keys
         FROM org o)
SELECT b.org, v.label, v.keys FROM base b CROSS JOIN LATERAL (VALUES
  ('own', b.own),
  ('own+foreign', b.own || b.foreign_keys),
  ('duplicates', b.own || b.own || b.own[1:3]),
  ('nulls', b.own || ARRAY[NULL::text, NULL]),
  ('empty', ARRAY[]::text[]),
  ('null array', NULL::text[]),
  ('unresolved', ARRAY['lead:' || rt.dx_uuid('u1'), 'client:' || rt.dx_uuid('u2'), 'lead:00000000-0000-0000-0000-000000000000']),
  ('malformed', ARRAY['recruit:' || rt.dx_uuid('m1'), 'lead:' || upper(rt.dx_uuid('m2')::text), 'lead:' || rt.dx_uuid('m3') || ' ',
                      ' lead:' || rt.dx_uuid('m4'), 'lead:' || rt.dx_uuid('m5') || E'\n', 'lead:' || replace(rt.dx_uuid('m6')::text, '-', ''),
                      'lead::' || rt.dx_uuid('m7'), 'lead:' || rt.dx_uuid('m8') || ':x', 'leads:' || rt.dx_uuid('m9'), 'Lead:' || rt.dx_uuid('m10'),
                      'lead:{' || rt.dx_uuid('m11') || '}', 'lead:' || overlay(rt.dx_uuid('m12')::text placing 'g' from 3 for 1),
                      'lead:' || overlay(rt.dx_uuid('m13')::text placing '-' from 3 for 1), 'lead:' || overlay(rt.dx_uuid('m14')::text placing 'é' from 3 for 1),
                      'lead:', 'client:', '', ':' || rt.dx_uuid('m15'), 'lead:' || rt.dx_uuid('m16') || 'a',
                      'lead:' || overlay(rt.dx_uuid('m17')::text placing '--' from 9 for 2), 'client:' || rt.dx_uuid('m18') || E'\t',
                      'lead:ffffffff-ffff-ffff-ffff-fffffffffff-', 'lead:-fffffff-ffff-ffff-ffff-ffffffffffff',
                      'lead:' || translate(rt.dx_uuid('m19')::text, '-', ':')]),
  ('malformed own', ARRAY(SELECT upper(k) FROM unnest(b.own[1:5]) k) || ARRAY(SELECT k || ' ' FROM unnest(b.own[1:5]) k) || b.own[6:10])
) v(label, keys);
INSERT INTO rt.dx_ist_cases SELECT NULL, 'null org', ARRAY['lead:' || rt.dx_uuid('null-org')];
CREATE FUNCTION rt.dx_identity_states(p_part text) RETURNS void LANGUAGE sql AS $$
  INSERT INTO rt.dx_results
  SELECT p_part, 'state_resolver', coalesce(c.org::text, 'null') || ':' || c.label, NULL, 'rows', 'rows', 'rows',
         CASE WHEN c.got = c.want THEN 'equal' ELSE 'mismatch' END, rt.dx_sha(c.got), rt.dx_sha(c.want),
         CASE WHEN c.got IS DISTINCT FROM c.want THEN jsonb_array_length(c.got) || ' rows <> ' || jsonb_array_length(c.want) || ' rows' END
    FROM (SELECT k.org, k.label,
                 (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.identity_key COLLATE "C"), '[]') FROM private.report_v3_identity_states(k.org, k.keys) r) AS got,
                 (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.identity_key COLLATE "C"), '[]') FROM rtref.report_v3_identity_states(k.org, k.keys) r) AS want
            FROM rt.dx_ist_cases k) c;
$$;

-- Journey helpers on the journey suite's organization J: member rows (both directions) and facts for agency, each
-- agent and a pair, over 6 windows and 5 as_of values (maturity boundaries included); then every by_agent row of the
-- one-read rollup against the baseline's per-agent computation.
CREATE TABLE rt.dx_journey_cases AS
SELECT a.label, a.agents, w.start_at, w.end_at, w.time_zone, sw.sold_from, sw.sold_until, x.as_of, y.s, y.e
  FROM (SELECT 'agency'::text AS label, NULL::uuid[] AS agents
        UNION ALL SELECT 'agent:' || p.last_name, ARRAY[p.id] FROM public.profiles p WHERE p.organization_id = rt.v3('J')
        UNION ALL SELECT 'pair', ARRAY(SELECT p.id FROM public.profiles p WHERE p.organization_id = rt.v3('J') ORDER BY p.id LIMIT 2)) a
 CROSS JOIN (VALUES ('2026-10-01'::date, '2026-10-31'::date), ('2026-09-01', '2026-09-30'), ('2026-10-05', '2026-10-05'),
                    ('2025-11-01', '2026-10-31'), ('2026-11-01', '2026-11-30'), ('2026-03-08', '2026-03-08')) y(s, e)
 CROSS JOIN (VALUES ('2026-12-15 00:00+00'::timestamptz), ('2026-10-06 18:00+00'), ('2026-11-05 07:00+00'),
                    ('2026-12-01 08:00+00'), ('2027-01-15 00:00+00')) x(as_of)
 CROSS JOIN LATERAL private.report_window(rt.v3('J'), y.s, y.e) w
 CROSS JOIN LATERAL private.report_v3_sold_window(w.start_date, w.end_date, (x.as_of AT TIME ZONE w.time_zone)::date) sw;
CREATE FUNCTION rt.dx_journey(p_part text, p_org uuid) RETURNS void LANGUAGE sql AS $$
  INSERT INTO rt.dx_results
  SELECT p_part, 'journey', r.label || ':' || r.s || '..' || r.e || '@' || r.as_of, NULL, 'rows', 'rows', 'rows',
         CASE WHEN r.facts_equal AND r.only_new = 0 AND r.only_ref = 0 THEN 'equal' ELSE 'mismatch' END,
         rt.dx_sha(r.got), rt.dx_sha(r.want),
         CASE WHEN NOT (r.facts_equal AND r.only_new = 0 AND r.only_ref = 0)
              THEN 'facts equal ' || r.facts_equal || ', members only new ' || r.only_new || ', only reference ' || r.only_ref END
    FROM (SELECT c.*, g.f AS got, h.f AS want, g.f = h.f AS facts_equal,
                 (SELECT count(*) FROM (SELECT * FROM private.report_v3_journey_members(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)
                                        EXCEPT ALL
                                        SELECT * FROM rtref.report_v3_journey_members(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)) d) AS only_new,
                 (SELECT count(*) FROM (SELECT * FROM rtref.report_v3_journey_members(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)
                                        EXCEPT ALL
                                        SELECT * FROM private.report_v3_journey_members(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)) d) AS only_ref
            FROM rt.dx_journey_cases c
           CROSS JOIN LATERAL (SELECT private.report_v3_journey_facts(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of) AS f) g
           CROSS JOIN LATERAL (SELECT rtref.report_v3_journey_facts(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of) AS f) h) r;
  INSERT INTO rt.dx_results
  SELECT p_part, 'journey_by_agent', r.label || ':' || r.s || '..' || r.e || '@' || r.as_of, NULL, 'rows', 'rows', 'rows',
         CASE WHEN r.got = r.want THEN 'equal' ELSE 'mismatch' END, rt.dx_sha(r.got), rt.dx_sha(r.want),
         CASE WHEN r.got IS DISTINCT FROM r.want THEN 'by_agent row differs' END
    FROM (SELECT c.*,
                 coalesce((SELECT b.facts FROM private.report_v3_journey_facts_by(p_org, NULL, true, c.time_zone, c.start_at, c.end_at,
                                                                                  c.sold_from, c.sold_until, c.as_of) b
                            WHERE b.grp = 'agent' AND b.agent_id = c.agents[1]),
                          (SELECT b.facts FROM private.report_v3_journey_facts_by(p_org, NULL, true, c.time_zone, c.start_at, c.end_at,
                                                                                  c.sold_from, c.sold_until, c.as_of) b
                            WHERE b.grp = 'empty')) AS got,
                 rtref.report_v3_journey_facts(p_org, c.agents, c.time_zone, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of) AS want
            FROM rt.dx_journey_cases c WHERE c.label LIKE 'agent:%') r;
$$;

-- The summary of one part: counts by kind and outcome, against the pinned totals.
CREATE FUNCTION rt.dx_summary(p_part text) RETURNS jsonb LANGUAGE sql AS $$
  SELECT jsonb_build_object(
    'part', p_part,
    'baseline_commit', (SELECT m.baseline_commit FROM rt.dx_manifest m),
    'approved_differences', (SELECT m.approved_differences FROM rt.dx_manifest m),
    'server_version', current_setting('server_version'),
    'by_kind', (SELECT jsonb_object_agg(k.kind, k.counts) FROM (
                  SELECT r.kind, jsonb_object_agg(r.outcome, r.n) AS counts
                    FROM (SELECT kind, outcome, count(*) AS n FROM rt.dx_results WHERE part = p_part GROUP BY 1, 2) r GROUP BY r.kind) k),
    'mismatches', (SELECT count(*) FROM rt.dx_results WHERE part = p_part AND outcome = 'mismatch'));
$$;

BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT rt.dx_grants(true);
SELECT rt.dx_reader_matrix();
SELECT rt.dx_identity_states('fixtures');
SELECT rt.dx_journey('fixtures', rt.v3('J'));
SELECT rt.dx_grants(false);
COMMIT;

-- What went wrong, if anything (printed before the assertions so a failure is diagnosable).
SELECT part, kind, label, reader, expected, cand, ref, detail FROM rt.dx_results WHERE outcome = 'mismatch' ORDER BY kind, label LIMIT 20;
SELECT rt.eq('differential: every case of the pinned reader inventory ran, and no other',
  (SELECT count(*) FROM rt.dx_results WHERE part = 'fixtures' AND kind = 'reader'), (SELECT t.cases FROM rt.dx_expected_totals t));
SELECT rt.eq('differential: the inventory holds exactly the pinned payload and refusal cases',
  (SELECT count(*) FILTER (WHERE expected = 'payload') || '|' || count(*) FILTER (WHERE expected LIKE 'refusal:%') FROM rt.dx_expected),
  (SELECT t.payload || '|' || t.refusal FROM rt.dx_expected_totals t));
SELECT rt.eq('differential: every expected payload is a payload on both sides and equal',
  (SELECT count(*) FROM rt.dx_results WHERE part = 'fixtures' AND kind = 'reader' AND outcome = 'payload_equal'), (SELECT t.payload FROM rt.dx_expected_totals t));
SELECT rt.eq('differential: every expected refusal has the same SQLSTATE and message on both sides',
  (SELECT count(*) FROM rt.dx_results WHERE part = 'fixtures' AND kind = 'reader' AND outcome = 'refusal_equal'), (SELECT t.refusal FROM rt.dx_expected_totals t));
SELECT rt.eq('differential: the identity-state resolver equals the baseline on every adversarial case',
  (SELECT count(*) FILTER (WHERE outcome = 'equal') || '/' || count(*) FROM rt.dx_results WHERE part = 'fixtures' AND kind = 'state_resolver'),
  (SELECT t.state_resolver || '/' || t.state_resolver FROM rt.dx_retained_totals t));
SELECT rt.eq('differential: journey facts and member rows equal the baseline on organization J',
  (SELECT count(*) FILTER (WHERE outcome = 'equal') || '/' || count(*) FROM rt.dx_results WHERE part = 'fixtures' AND kind = 'journey'),
  (SELECT t.journey || '/' || t.journey FROM rt.dx_retained_totals t));
SELECT rt.eq('differential: every by_agent row of the one-read rollup equals the baseline''s per-agent computation',
  (SELECT count(*) FILTER (WHERE outcome = 'equal') || '/' || count(*) FROM rt.dx_results WHERE part = 'fixtures' AND kind = 'journey_by_agent'),
  (SELECT t.journey_by_agent || '/' || t.journey_by_agent FROM rt.dx_retained_totals t));
SELECT rt.eq('differential: no mismatch on the fixtures', (SELECT count(*) FROM rt.dx_results WHERE part = 'fixtures' AND outcome = 'mismatch'), 0::bigint);

-- Self-controls: the harness bites. Each plants one difference inside a rolled-back subtransaction and requires
-- the comparison to report a mismatch.
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT rt.dx_grants(true);
SELECT rt.dx_must_match('control baseline: the unplanted case matches', rt.v3('ADM1'), rt.v3('O1'), 'scope', NULL, NULL, NULL, NULL, 'payload');
-- (1) A payload difference in the code under test.
SELECT rt.reject_mutation('public.get_report_scope_v3(text)', '''max_range_days'', 366', '''max_range_days'', 365',
  $probe$SELECT rt.dx_must_match('control: planted payload difference', rt.v3('ADM1'), rt.v3('O1'), 'scope', NULL, NULL, NULL, NULL, 'payload')$probe$,
  'differential mismatch: control: planted payload difference');
-- (2) A refusal with a different message in the code under test.
SELECT rt.reject_mutation('public.get_report_summary_v3(date,date,uuid,text)',
  'SELECT * INTO a FROM private.report_access_v2(p_requested_scope, p_agent_id);',
  'RAISE EXCEPTION ''planted refusal'' USING ERRCODE = ''42501''; SELECT * INTO a FROM private.report_access_v2(p_requested_scope, p_agent_id);',
  $probe$SELECT rt.dx_must_match('control: planted refusal difference', e.uid, e.org, 'summary', e.start_date, e.end_date, e.agent, e.scope, e.expected)
           FROM (SELECT rt.v3(x.who) AS uid, rt.v3(x.org) AS org, x.start_date, x.end_date, rt.v3(x.agent) AS agent, x.scope, x.expected
                   FROM rt.dx_expected x WHERE x.reader = 'summary' AND x.expected LIKE 'refusal:42501'
                  ORDER BY x.who, x.scope, x.start_date LIMIT 1) e$probe$,
  'differential mismatch: control: planted refusal difference');
-- (3) The same error on both sides where a payload is expected: a matching error never stands in for a payload.
SELECT rt.reject_mutation('private.report_access_v2(text,uuid)', ' SELECT * INTO a FROM private.campaign_actor();',
  ' RAISE EXCEPTION ''planted shared failure'' USING ERRCODE = ''42501''; SELECT * INTO a FROM private.campaign_actor();',
  $probe$SELECT rt.dx_must_match('control: matching error where a payload is expected', rt.v3('ADM1'), rt.v3('O1'), 'summary', '2026-10-01', '2026-10-31', NULL, NULL, 'payload')$probe$,
  'differential mismatch: control: matching error where a payload is expected');
SELECT rt.dx_grants(false);
COMMIT;
SELECT rt.eq('differential: the planted controls leave no residue; only the unplanted control case remains, and it matches',
  (SELECT string_agg(label || '=' || outcome, ',') FROM rt.dx_results WHERE part = 'control'),
  'control baseline: the unplanted case matches=payload_equal');
SELECT rt.assert_sealed_v3(true, false);
SELECT rt.eq('differential: the reference is not client-executable',
  (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'rtref' AND (has_function_privilege('authenticated', p.oid, 'EXECUTE') OR has_function_privilege('anon', p.oid, 'EXECUTE'))), 0::bigint);

\pset tuples_only on
\pset format unaligned
\o :dx_cases
SELECT row_to_json(r) FROM (SELECT part, kind, label, reader, expected, cand, ref, outcome, cand_sha256, ref_sha256
                              FROM rt.dx_results WHERE part = 'fixtures' ORDER BY kind, label) r;
\o :dx_summary
SELECT jsonb_pretty(rt.dx_summary('fixtures'));
\o
\pset tuples_only off
\pset format aligned
SELECT rt.dx_summary('fixtures') AS differential_fixtures;

-- @@differential-scale@@
-- Part 2: the 500k scale organization of reports_v3_performance.sql (loaded by the runner after part 1). The scale
-- reader cases come from the pinned inventory (rt.dx_scale_expected); the call facts, the identity-state sample and
-- the journey helpers are compared directly.
\if :{?dx_scale_cases}
\else
\set dx_scale_cases /dev/null
\endif
\if :{?dx_scale_summary}
\else
\set dx_scale_summary /dev/null
\endif
-- The journey reader cases of the inventory compare the public reader with the reviewed baseline's reader. The
-- baseline's journey reader takes 31 minutes (agency, 1 day) to more than 2 hours (agency 30 and 366 days) per call at
-- this scale, more than the CI job's remaining time, so they run only when REPORTS_V3_DX_JOURNEY_SCALE=1; otherwise
-- they are reported as not run (never as compared).
\getenv dx_journey_scale REPORTS_V3_DX_JOURNEY_SCALE
\if :{?dx_journey_scale}
\else
\set dx_journey_scale 0
\endif
SELECT rt.eq('differential at scale: REPORTS_V3_DX_JOURNEY_SCALE is unset, 0 or 1', :'dx_journey_scale' IN ('0', '1'), true);
SELECT rt.eq('differential at scale: the journey reader cases pinned (windows, scopes, the agent filter, annual agency)',
  (SELECT string_agg(concat_ws(':', e.persona, e.scope, e.days, coalesce(e.filter_agent::text, '-'), e.expected), ' ' ORDER BY e.persona, e.days, e.filter_agent NULLS FIRST)
     FROM rt.dx_scale_expected e WHERE e.reader = 'journey'),
  '0:agency:1:-:payload 0:agency:30:-:payload 0:agency:366:-:payload 0:agency:366:7:payload 1:team:30:-:payload 7:personal:366:-:payload');
SET statement_timeout = 0;
SET jit = off;
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT rt.dx_grants(true);
SELECT count(*) AS scale_reader_cases FROM (
  SELECT rt.dx_case('scale', concat_ws(':', 'persona-' || e.persona, e.scope, coalesce('agent-' || e.filter_agent, '-'), e.reader,
                                       coalesce(e.days || 'd', '-')),
                    rt.perf_agent(e.persona), m.org, e.reader, m.end_date - (e.days - 1), m.end_date,
                    CASE WHEN e.filter_agent IS NOT NULL THEN rt.perf_agent(e.filter_agent) END, e.scope, e.expected)
    FROM rt.dx_scale_expected e, rt.perf_meta m
   WHERE e.reader <> 'journey' OR :'dx_journey_scale' = '1'
   ORDER BY e.reader, e.persona, e.days, e.filter_agent NULLS FIRST) x;
-- Call facts over the 366-day window: the code under test against the pinned v2 rows on every carried column, and
-- against the baseline's v3 rows on every column.
CREATE TEMP TABLE dx_window AS SELECT w.start_at, w.end_at FROM rt.perf_meta m, LATERAL private.report_window(m.org, m.end_date - 365, m.end_date) w;
CREATE TEMP TABLE dx_v3 AS SELECT f.* FROM dx_window w, rt.perf_meta m, LATERAL private.report_v3_call_facts(m.org, w.start_at, w.end_at) f;
CREATE TEMP TABLE dx_ref AS SELECT f.* FROM dx_window w, rt.perf_meta m, LATERAL rtref.report_v3_call_facts(m.org, w.start_at, w.end_at) f;
CREATE TEMP TABLE dx_v2 AS SELECT v.* FROM dx_window w, rt.perf_meta m, LATERAL private.report_call_facts(m.org, w.start_at, w.end_at, NULL) v;
INSERT INTO rt.dx_results
SELECT 'scale', 'call_facts', 'v3 = pinned v2 (carried columns), 366 days', NULL, 'rows', 'rows', 'rows',
       CASE WHEN d.v3_rows = d.v2_rows AND d.only_v3 = 0 AND d.only_v2 = 0 THEN 'equal' ELSE 'mismatch' END, NULL, NULL,
       d.v3_rows || ' v3 rows, ' || d.v2_rows || ' v2 rows, ' || d.only_v3 || ' only v3, ' || d.only_v2 || ' only v2'
  FROM (SELECT (SELECT count(*) FROM dx_v3) AS v3_rows, (SELECT count(*) FROM dx_v2) AS v2_rows,
               (SELECT count(*) FROM (SELECT call_id, placing_agent_id, direction_class, created_at, duration_seconds, campaign_id, lead_id,
                                             lead_source, disposition_key, disposition_name, disposition_color, disp_counts_contacted, disp_converts,
                                             disp_dnc, disp_callback, disp_appointment, is_contacted FROM dx_v3
                                      EXCEPT ALL
                                      SELECT call_id, agent_id, direction_class, created_at, duration_seconds, campaign_id, lead_id, lead_source,
                                             disposition_key, disposition_name, disposition_color, disp_counts_contacted, disp_converts, disp_dnc,
                                             disp_callback, disp_appointment, is_contacted FROM dx_v2) x) AS only_v3,
               (SELECT count(*) FROM (SELECT call_id, agent_id, direction_class, created_at, duration_seconds, campaign_id, lead_id, lead_source,
                                             disposition_key, disposition_name, disposition_color, disp_counts_contacted, disp_converts, disp_dnc,
                                             disp_callback, disp_appointment, is_contacted FROM dx_v2
                                      EXCEPT ALL
                                      SELECT call_id, placing_agent_id, direction_class, created_at, duration_seconds, campaign_id, lead_id,
                                             lead_source, disposition_key, disposition_name, disposition_color, disp_counts_contacted, disp_converts,
                                             disp_dnc, disp_callback, disp_appointment, is_contacted FROM dx_v3) x) AS only_v2) d;
INSERT INTO rt.dx_results
SELECT 'scale', 'call_facts', 'v3 = baseline v3 (every column), 366 days', NULL, 'rows', 'rows', 'rows',
       CASE WHEN d.only_new = 0 AND d.only_ref = 0 AND d.n = d.r THEN 'equal' ELSE 'mismatch' END, NULL, NULL,
       d.n || ' rows, ' || d.r || ' reference rows, ' || d.only_new || ' only new, ' || d.only_ref || ' only reference'
  FROM (SELECT (SELECT count(*) FROM dx_v3) AS n, (SELECT count(*) FROM dx_ref) AS r,
               (SELECT count(*) FROM (SELECT * FROM dx_v3 EXCEPT ALL SELECT * FROM dx_ref) x) AS only_new,
               (SELECT count(*) FROM (SELECT * FROM dx_ref EXCEPT ALL SELECT * FROM dx_v3) x) AS only_ref) d;
-- The identity-state resolver on a deterministic sample of the scale organization's keys.
INSERT INTO rt.dx_results
SELECT 'scale', 'state_resolver', 'sample of ' || cardinality(k.keys) || ' keys', NULL, 'rows', 'rows', 'rows',
       CASE WHEN g.v = h.v THEN 'equal' ELSE 'mismatch' END, rt.dx_sha(g.v), rt.dx_sha(h.v), NULL
  FROM (SELECT m.org, ARRAY(SELECT 'lead:' || l.id FROM public.leads l WHERE l.organization_id = m.org AND abs(hashtext(l.id::text)) % 8 = 0 ORDER BY l.id)
                      || ARRAY(SELECT 'client:' || c.id FROM public.clients c WHERE c.organization_id = m.org AND abs(hashtext(c.id::text)) % 2 = 0 ORDER BY c.id)
                      || ARRAY['lead:' || rt.dx_uuid('scale-unknown'), 'client:' || rt.dx_uuid('scale-unknown-client')] AS keys
          FROM rt.perf_meta m) k
 CROSS JOIN LATERAL (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.identity_key COLLATE "C"), '[]') AS v FROM private.report_v3_identity_states(k.org, k.keys) r) g
 CROSS JOIN LATERAL (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.identity_key COLLATE "C"), '[]') AS v FROM rtref.report_v3_identity_states(k.org, k.keys) r) h;
-- Journey helpers at scale: personal scope (agent 7), the 30-day window ending at the fixture's end date.
INSERT INTO rt.dx_results
SELECT 'scale', 'journey', 'personal agent 7, 30 days', NULL, 'rows', 'rows', 'rows',
       CASE WHEN f.got = f.want AND f.only_new = 0 AND f.only_ref = 0 THEN 'equal' ELSE 'mismatch' END, rt.dx_sha(f.got), rt.dx_sha(f.want),
       f.members || ' member rows, ' || f.only_new || ' only new, ' || f.only_ref || ' only reference'
  FROM (SELECT private.report_v3_journey_facts(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of) AS got,
               rtref.report_v3_journey_facts(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of) AS want,
               (SELECT count(*) FROM private.report_v3_journey_members(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)) AS members,
               (SELECT count(*) FROM (SELECT * FROM private.report_v3_journey_members(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)
                                      EXCEPT ALL
                                      SELECT * FROM rtref.report_v3_journey_members(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)) d) AS only_new,
               (SELECT count(*) FROM (SELECT * FROM rtref.report_v3_journey_members(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)
                                      EXCEPT ALL
                                      SELECT * FROM private.report_v3_journey_members(c.org, c.agents, c.tz, c.start_at, c.end_at, c.sold_from, c.sold_until, c.as_of)) d) AS only_ref
          FROM (SELECT m.org, ARRAY[rt.perf_agent(7)] AS agents, m.tz, w.start_at, w.end_at, sw.sold_from, sw.sold_until, now() AS as_of
                  FROM rt.perf_meta m,
                       LATERAL private.report_window(m.org, m.end_date - 29, m.end_date) w,
                       LATERAL private.report_v3_sold_window(w.start_date, w.end_date, (now() AT TIME ZONE w.time_zone)::date) sw) c) f;
SELECT rt.dx_grants(false);
COMMIT;

SELECT part, kind, label, reader, expected, cand, ref, detail FROM rt.dx_results WHERE part = 'scale' AND (outcome = 'mismatch' OR kind <> 'reader') ORDER BY kind, label;
SELECT rt.eq('differential at scale: every pinned scale reader case ran (the journey reader cases when enabled)',
  (SELECT count(*) FROM rt.dx_results WHERE part = 'scale' AND kind = 'reader'),
  (SELECT count(*) FROM rt.dx_scale_expected e WHERE e.reader <> 'journey' OR :'dx_journey_scale' = '1'));
SELECT rt.eq('differential at scale: the journey reader cases compared equal when enabled, and absent otherwise',
  (SELECT count(*) FILTER (WHERE r.outcome = 'payload_equal') || '/' || count(*) FROM rt.dx_results r WHERE r.part = 'scale' AND r.kind = 'reader' AND r.reader = 'journey'),
  CASE WHEN :'dx_journey_scale' = '1' THEN '6/6' ELSE '0/0' END);
SELECT CASE WHEN :'dx_journey_scale' = '1' THEN 'differential at scale: journey reader cases compared with the baseline: 6 of 6 payload_equal'
            ELSE 'differential at scale: journey reader cases NOT RUN (6 pinned; set REPORTS_V3_DX_JOURNEY_SCALE=1, 31 minutes to more than 2 hours per baseline call)'
       END AS journey_reader_scale;
SELECT rt.eq('differential at scale: the pinned v2 call rows, the baseline v3 rows, the resolver sample and the journey helpers all compared',
  (SELECT count(*) FROM rt.dx_results WHERE part = 'scale' AND kind <> 'reader'), 4::bigint);
SELECT rt.eq('differential at scale: no mismatch', (SELECT count(*) FROM rt.dx_results WHERE part = 'scale' AND outcome = 'mismatch'), 0::bigint);
SELECT rt.assert_sealed_v3(true, false);

\pset tuples_only on
\pset format unaligned
\o :dx_scale_cases
SELECT row_to_json(r) FROM (SELECT part, kind, label, reader, expected, cand, ref, outcome, cand_sha256, ref_sha256, detail
                              FROM rt.dx_results WHERE part = 'scale' ORDER BY kind, label) r;
\o :dx_scale_summary
SELECT jsonb_pretty(rt.dx_summary('scale') || jsonb_build_object('journey_reader_cases',
         CASE WHEN :'dx_journey_scale' = '1' THEN 'compared' ELSE 'not run (REPORTS_V3_DX_JOURNEY_SCALE unset)' END));
\o
\pset tuples_only off
\pset format aligned
SELECT rt.dx_summary('scale') || jsonb_build_object('journey_reader_cases',
         CASE WHEN :'dx_journey_scale' = '1' THEN 'compared' ELSE 'not run (REPORTS_V3_DX_JOURNEY_SCALE unset)' END) AS differential_scale;
